    Bug 1999998 - Populate boolean pref when Yahoo or AOL Oauth seen. r=arschmitz,sancus

    Differential Revision: https://phabricator.services.mozilla.com/D272502

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index 2779a72302b..4bdb9446ab5 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -1483,6 +1483,11 @@ pref("mail.inappnotifications.refreshInterval", 21600000);
 // Disables all filtering of in-app notifications, useful for testing.
 pref("mail.inappnotifications.bypass-filtering", false);

+// Whether Yahoo/AOL/ATT OAuth user is detected.
+// Used to notify about upcoming changes via in-app notification.
+// TODO: Remove this when PKCE is fully rolled out for Yahoo/AOL/AT&T
+pref("mail.inappnotifications.pkceUpgradeForYahooAol", false);
+
 #ifdef NIGHTLY_BUILD
 // Enable the new experimental conversation view based on Gloda.
 pref("mail.thread.conversation.enabled", false);
diff --git a/mailnews/base/src/OAuth2Module.sys.mjs b/mailnews/base/src/OAuth2Module.sys.mjs
index d5f67030c0f..6b2676805d2 100644
--- a/mailnews/base/src/OAuth2Module.sys.mjs
+++ b/mailnews/base/src/OAuth2Module.sys.mjs
@@ -71,6 +71,25 @@ OAuth2Module.prototype = {
     }

     const { issuer, allScopes, requiredScopes } = details;
+
+    // Set pref for Yahoo/AOL/AT&T users if applicable
+    // TODO: Remove this when PKCE is fully rolled out for Yahoo/AOL/AT&T
+    const yahooLikeIssuer = ["login.yahoo.com", "login.aol.com"].includes(
+      details.issuer
+    );
+    if (
+      yahooLikeIssuer &&
+      !Services.prefs.getBoolPref(
+        "mail.inappnotifications.pkceUpgradeForYahooAol",
+        false
+      )
+    ) {
+      Services.prefs.setBoolPref(
+        "mail.inappnotifications.pkceUpgradeForYahooAol",
+        true
+      );
+    }
+
     // Find the app key we need for the OAuth2 string. Eventually, this should
     // be using dynamic client registration, but there are no current
     // implementations that we can test this with.
